package com.campusconnect.attendance;
import com.campusconnect.course.*; import com.campusconnect.enrollment.*; import com.campusconnect.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/attendance") public class AttendanceController {private final AttendanceRepository records; private final CourseRepository courses; private final UserRepository users; private final EnrollmentRepository enrollments; public AttendanceController(AttendanceRepository r,CourseRepository c,UserRepository u,EnrollmentRepository e){records=r;courses=c;users=u;enrollments=e;}
public record MarkRequest(@NotNull Long courseId,@NotNull Long studentId,@NotNull LocalDate date,@NotNull AttendanceRecord.Status status){}
@GetMapping public List<Map<String,Object>> mine(Principal p,Authentication auth){boolean staff=auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_FACULTY")||a.getAuthority().equals("ROLE_ADMIN"));return (staff?records.findAll().stream().sorted((a,b)->b.getAttendanceDate().compareTo(a.getAttendanceDate())).toList():records.findByStudentEmailOrderByAttendanceDateDesc(p.getName())).stream().map(this::dto).toList();}
@GetMapping("/course/{courseId}") @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public List<Map<String,Object>> course(@PathVariable Long courseId,@RequestParam(required=false) LocalDate date){return (date==null?records.findByCourseIdOrderByAttendanceDateDesc(courseId):records.findByCourseIdAndAttendanceDate(courseId,date)).stream().map(this::dto).toList();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public Map<String,Object> mark(@Valid @RequestBody MarkRequest r,Principal p){var c=courses.findById(r.courseId()).orElseThrow(()->new IllegalArgumentException("Course not found"));var s=users.findById(r.studentId()).orElseThrow(()->new IllegalArgumentException("Student not found"));if(s.getRole()!=Role.STUDENT)throw new IllegalArgumentException("Attendance can only be recorded for students");if(enrollments.findByCourseIdAndStudentEmail(r.courseId(),s.getEmail()).isEmpty())throw new IllegalArgumentException("Student is not enrolled in this course");var m=users.findByEmailIgnoreCase(p.getName()).orElseThrow();var old=records.findByCourseIdAndStudentEmailAndAttendanceDate(r.courseId(),s.getEmail(),r.date());var a=old.orElseGet(()->new AttendanceRecord(c,s,m,r.date(),r.status()));a.setStatus(r.status());return dto(records.save(a));}
@GetMapping("/summary") public Map<String,Object> summary(Principal p){var all=records.findByStudentEmailOrderByAttendanceDateDesc(p.getName());long present=all.stream().filter(a->a.getStatus()==AttendanceRecord.Status.PRESENT).count();long late=all.stream().filter(a->a.getStatus()==AttendanceRecord.Status.LATE).count();long absent=all.stream().filter(a->a.getStatus()==AttendanceRecord.Status.ABSENT).count();return Map.of("total",all.size(),"present",present,"late",late,"absent",absent,"percentage",all.isEmpty()?0:Math.round((present+late)*1000.0/all.size())/10.0);}
private Map<String,Object> dto(AttendanceRecord a){return Map.of("id",a.getId(),"courseId",a.getCourse().getId(),"courseTitle",a.getCourse().getTitle(),"courseCode",a.getCourse().getCode(),"studentId",a.getStudent().getId(),"studentName",a.getStudent().getName(),"studentEmail",a.getStudent().getEmail(),"date",a.getAttendanceDate(),"status",a.getStatus());}}
